export const lessonById = new Map(LESSONS.map((l) => [l.id, l]));
export const lessonsForSkill = (skillId: string) => LESSONS.filter((l) => l.skillIds.includes(skillId));
export const lessonsForSchool = (schoolId: string) => LESSONS.filter((l) => l.schoolId === schoolId);
